#!/usr/bin/env julia
# Analyze one extracted problem instance (Linear vs Bezier) end-to-end.
#
# Usage:
#   julia -t 1 analyze_problem_instance.jl /tmp/case.jl [n_runs] [n_evals] [warmup]
#
# where /tmp/case.jl is generated by extract_problem_instance.py and defines:
#   DEGREE, BEZIER_DEGREE, START_COEFFS, TARGET_COEFFS, GAMMA, BEZIER_CTRL

cd(@__DIR__)
include("linear_univar.jl")
include("bezier_univar.jl")

function _micro_eval_report(degree::Int, bezier_degree::Int, ctrl::Matrix{ComplexF64}, n_evals::Int)
    ncoef = degree + 1
    endpoints = zeros(ComplexF64, 2, ncoef)
    endpoints[1, :] .= ctrl[1, :]
    endpoints[2, :] .= ctrl[end, :]
    H_lin = LinearUnivarPoly(degree, endpoints, zeros(ComplexF64, ncoef), zeros(ComplexF64, ncoef))
    update_linear_diff!(H_lin)

    H_bez = make_homotopy_univar(degree, bezier_degree; seed=1)
    copyto!(H_bez.ctrl, ctrl)
    compute_diffs!(H_bez.diffs, H_bez.ctrl, H_bez.bezier_degree, H_bez.max_derivative_order)

    τs = rand(n_evals)
    x0 = [0.5 + 0.3im]
    u = zeros(ComplexF64, 1)
    U = zeros(ComplexF64, 1, 1)

    t_lin0 = @elapsed for τ in τs
        eval_coeffs0!(H_lin, τ)
    end
    t_bez0 = @elapsed for τ in τs
        eval_coeffs0!(H_bez, τ)
    end
    t_lin_j = @elapsed for τ in τs
        eval_coeffs0!(H_lin, τ)
        px, dpx = poly_and_deriv_horner(H_lin.ceff0, x0[1])
        u[1] = px
        U[1,1] = dpx
    end
    t_bez_j = @elapsed for τ in τs
        eval_coeffs0!(H_bez, τ)
        px, dpx = poly_and_deriv_horner(H_bez.ceff0, x0[1])
        u[1] = px
        U[1,1] = dpx
    end
    t_lin_t1 = @elapsed for _ in τs
        u[1] = -poly_only_horner(H_lin.ceff1, x0[1])
    end
    t_bez_t1 = @elapsed for τ in τs
        eval_coeffs_k!(H_bez.ceff1, H_bez, τ, 1)
        u[1] = -poly_only_horner(H_bez.ceff1, x0[1])
    end

    per_lin0 = t_lin0 / n_evals * 1e6
    per_bez0 = t_bez0 / n_evals * 1e6
    per_lin_j = t_lin_j / n_evals * 1e6
    per_bez_j = t_bez_j / n_evals * 1e6
    per_lin_t1 = t_lin_t1 / n_evals * 1e6
    per_bez_t1 = t_bez_t1 / n_evals * 1e6

    println()
    println("## Micro eval (same extracted ctrl) n_evals=$n_evals")
    println("  eval_coeffs0! only (μs):      Linear ", round(per_lin0; digits=4), "  Bezier ", round(per_bez0; digits=4), "  ratio ", round(per_bez0 / per_lin0; digits=3))
    println("  evaluate_and_jacobian! (μs):  Linear ", round(per_lin_j; digits=4), "  Bezier ", round(per_bez_j; digits=4), "  ratio ", round(per_bez_j / per_lin_j; digits=3))
    println("  taylor! k=1 (μs):             Linear ", round(per_lin_t1; digits=4), "  Bezier ", round(per_bez_t1; digits=4), "  ratio ", round(per_bez_t1 / per_lin_t1; digits=3))
end

function main()
    if length(ARGS) < 1
        println("Usage: julia -t 1 analyze_problem_instance.jl /path/to/case.jl [n_runs] [n_evals] [warmup]")
        return
    end
    case_file = ARGS[1]
    n_runs = length(ARGS) >= 2 ? parse(Int, ARGS[2]) : 20
    n_evals = length(ARGS) >= 3 ? parse(Int, ARGS[3]) : 100_000
    warmup = length(ARGS) >= 4 ? parse(Int, ARGS[4]) : 1

    include(case_file)

    degree = DEGREE
    bezier_degree = BEZIER_DEGREE
    start_path = GAMMA .* START_COEFFS
    target = TARGET_COEFFS
    ctrl = BEZIER_CTRL

    println("Analyze extracted case: degree=$degree bezier_degree=$bezier_degree n_runs=$n_runs warmup=$warmup threads=$(Threads.nthreads())")
    if Threads.nthreads() != 1
        println("  (recommended: julia -t 1 ...)")
    end

    init_linear_univar(; degree, seed=0)
    init_bezier_univar(; degree, bezier_degree, seed=0)

    # --- repeated runs: per i, (true → steps/Newton only) then (false → time + eval counts/timings) ---
    LINEAR_ENABLE_EVAL_COUNTS[] = false
    LINEAR_ENABLE_EVAL_TIMINGS[] = false
    for _ in 1:warmup
        track_linear_paths_univar(degree, start_path, target; compute_newton_iters=false)
    end
    reset_linear_eval_counts!()
    reset_linear_eval_timings!()
    total_time_lin = 0.0
    newton_sum_lin = 0
    step_sum_lin = 0
    for _ in 1:n_runs
        LINEAR_ENABLE_EVAL_COUNTS[] = false
        LINEAR_ENABLE_EVAL_TIMINGS[] = false
        out_true = track_linear_paths_univar(degree, start_path, target; compute_newton_iters=true)
        step_sum_lin += out_true.total_step_attempts
        newton_sum_lin += out_true.total_newton_iterations
        LINEAR_ENABLE_EVAL_COUNTS[] = true
        LINEAR_ENABLE_EVAL_TIMINGS[] = true
        out_false = track_linear_paths_univar(degree, start_path, target; compute_newton_iters=false)
        total_time_lin += out_false.tracking_time_sec
    end
    n_eaj_lin = get(linear_eval_counts_total(), "evaluate_and_jacobian", 0)
    LINEAR_ENABLE_EVAL_COUNTS[] = false
    lin_timing = linear_eval_timings_total()
    LINEAR_ENABLE_EVAL_TIMINGS[] = false

    ENABLE_EVAL_COUNTS[] = false
    ENABLE_EVAL_TIMINGS[] = false
    for _ in 1:warmup
        track_bezier_paths_univar(degree, bezier_degree, ctrl; compute_newton_iters=false)
    end
    reset_eval_counts!()
    reset_eval_timings!()
    total_time_bez = 0.0
    newton_sum_bez = 0
    step_sum_bez = 0
    for _ in 1:n_runs
        ENABLE_EVAL_COUNTS[] = false
        ENABLE_EVAL_TIMINGS[] = false
        out_true = track_bezier_paths_univar(degree, bezier_degree, ctrl; compute_newton_iters=true)
        step_sum_bez += out_true.total_step_attempts
        newton_sum_bez += out_true.total_newton_iterations
        ENABLE_EVAL_COUNTS[] = true
        ENABLE_EVAL_TIMINGS[] = true
        out_false = track_bezier_paths_univar(degree, bezier_degree, ctrl; compute_newton_iters=false)
        total_time_bez += out_false.tracking_time_sec
    end
    n_eaj_bez = get(eval_counts_total(), "evaluate_and_jacobian", 0)
    ENABLE_EVAL_COUNTS[] = false
    bez_timing = eval_timings_total()
    ENABLE_EVAL_TIMINGS[] = false

    # time_per_newton = sum(false tracking time) / sum(Newton from paired true runs)
    time_per_newton_lin = newton_sum_lin > 0 ? (total_time_lin / newton_sum_lin) * 1e6 : NaN
    time_per_newton_bez = newton_sum_bez > 0 ? (total_time_bez / newton_sum_bez) * 1e6 : NaN
    mean_track_lin = total_time_lin / n_runs
    mean_track_bez = total_time_bez / n_runs
    track_ratio = mean_track_lin > 0 ? mean_track_bez / mean_track_lin : NaN
    println()
    println("## Repeated runs (n_runs=$n_runs, warmup=$warmup; each i: true=steps/Newton only, false=time+counts)")
    println("  Mean tracking time (s): Linear ", round(mean_track_lin; digits=6),
            "  Bezier ", round(mean_track_bez; digits=6), "  ratio ", round(track_ratio; digits=4), " (Bezier/Linear)")
    mean_step_lin = step_sum_lin / n_runs
    mean_step_bez = step_sum_bez / n_runs
    step_ratio = mean_step_lin > 0 ? mean_step_bez / mean_step_lin : NaN
    println("  Mean step attempts: Linear ", round(mean_step_lin; digits=4),
            "  Bezier ", round(mean_step_bez; digits=4), "  ratio ", round(step_ratio; digits=4), " (Bezier/Linear)")
    mean_newton_lin = newton_sum_lin / n_runs
    mean_newton_bez = newton_sum_bez / n_runs
    newton_ratio = mean_newton_lin > 0 ? mean_newton_bez / mean_newton_lin : NaN
    mean_eaj_lin = n_eaj_lin / n_runs
    mean_eaj_bez = n_eaj_bez / n_runs
    eaj_ratio = mean_eaj_lin > 0 ? mean_eaj_bez / mean_eaj_lin : NaN
    println("  Mean Newton iterations: Linear ", round(mean_newton_lin; digits=4),
            "  Bezier ", round(mean_newton_bez; digits=4), "  ratio ", round(newton_ratio; digits=4), " (Bezier/Linear)")
    println("  Mean evaluate_and_jacobian: Linear ", round(mean_eaj_lin; digits=4),
            "  Bezier ", round(mean_eaj_bez; digits=4), "  ratio ", round(eaj_ratio; digits=4), " (Bezier/Linear)")
    println("  time per Newton (μs): Linear ", round(time_per_newton_lin; digits=4), "  Bezier ", round(time_per_newton_bez; digits=4),
            "  ratio ", round(time_per_newton_bez / time_per_newton_lin; digits=4))
    lin_eaj0 = get(lin_timing, "eaj_eval_coeffs0_sec", 0.0)
    lin_eajh = get(lin_timing, "eaj_poly_and_deriv_sec", 0.0)
    bez_eaj0 = get(bez_timing, "eaj_eval_coeffs0_sec", 0.0)
    bez_eajh = get(bez_timing, "eaj_poly_and_deriv_sec", 0.0)
    lin_eaj0_us = n_eaj_lin > 0 ? lin_eaj0 / n_eaj_lin * 1e6 : NaN
    lin_eajh_us = n_eaj_lin > 0 ? lin_eajh / n_eaj_lin * 1e6 : NaN
    bez_eaj0_us = n_eaj_bez > 0 ? bez_eaj0 / n_eaj_bez * 1e6 : NaN
    bez_eajh_us = n_eaj_bez > 0 ? bez_eajh / n_eaj_bez * 1e6 : NaN
    println("  e&j breakdown (μs/call):")
    println("    eval_coeffs0!: Linear ", round(lin_eaj0_us; digits=4), "  Bezier ", round(bez_eaj0_us; digits=4),
            "  ratio ", round(bez_eaj0_us / lin_eaj0_us; digits=3))
    println("    poly+deriv:    Linear ", round(lin_eajh_us; digits=4), "  Bezier ", round(bez_eajh_us; digits=4),
            "  ratio ", round(bez_eajh_us / lin_eajh_us; digits=3))
    bez_counts_rep = eval_counts_total()
    n_c0_hit = get(bez_counts_rep, "eval_coeffs0_cache_hit", 0)
    n_c0_miss = get(bez_counts_rep, "eval_coeffs0_cache_miss", 0)
    n_c0_total = n_c0_hit + n_c0_miss
    c0_hit_rate = n_c0_total > 0 ? (n_c0_hit / n_c0_total) * 100.0 : NaN
    println("  eval_coeffs0 cache (sum over false runs): hit=", n_c0_hit, " miss=", n_c0_miss,
            "  mean hit/run=", round(n_c0_hit / n_runs; digits=2), " mean miss/run=", round(n_c0_miss / n_runs; digits=2),
            "  hit_rate=", round(c0_hit_rate; digits=2), "%")

    # --- call-count share in all solution paths tracking (single run): Linear + Bezier ---
    reset_linear_eval_counts!()
    LINEAR_ENABLE_EVAL_COUNTS[] = true
    out_lin_calls = track_linear_paths_univar(degree, start_path, target)
    LINEAR_ENABLE_EVAL_COUNTS[] = false
    lin_counts = linear_eval_counts_total()

    reset_eval_counts!()
    ENABLE_EVAL_COUNTS[] = true
    out_bez_calls = track_bezier_paths_univar(degree, bezier_degree, ctrl)
    ENABLE_EVAL_COUNTS[] = false
    bez_counts = eval_counts_total()
    println()
    println("## Linear call counts (all solution paths tracking)")
    println("  tracking_time_sec = ", round(out_lin_calls.tracking_time_sec; digits=6))
    for (k, v) in sort(collect(lin_counts), by=x->x[2], rev=true)
        println("  ", rpad(k, 25), " ", v)
    end
    println()
    println("## Bezier call counts (all solution paths tracking)")
    println("  tracking_time_sec = ", round(out_bez_calls.tracking_time_sec; digits=6))
    for (k, v) in sort(collect(bez_counts), by=x->x[2], rev=true)
        println("  ", rpad(k, 25), " ", v)
    end

    _micro_eval_report(degree, bezier_degree, ctrl, n_evals)
    println()
    println("Done. Use micro-eval ratios + call counts to identify where Bezier spends extra time.")
end

main()

